import { getMessageSchema } from "../agent/schemas/agent.schema.js";
import { privateSha256Hex } from "../security/private-sha256.js";
import { privateJsonStringify } from "../security/private-json.js";
import { snapshotDurableValue } from "./durable-run-home-schema.js";
/** Immutable data provenance only; history never confers current-run effect authority. */
export function recoveryHistoryMessageDigest(message) {
    const normalized = getMessageSchema().omit({ metadata: true }).strict().parse({
        id: message.id,
        role: message.role,
        parts: message.parts,
    });
    return privateSha256Hex(privateJsonStringify(snapshotDurableValue({
        id: message.id,
        role: message.role,
        parts: normalized.parts,
    })));
}
